// Assembles src/xtermVendor.generated.ts, dist/build.json and
// THIRD_PARTY_NOTICES.txt from the built runtime IIFE and xterm's CSS.
// Invoked by scripts/build-xterm-vendor.sh after `bun build`.
// Reproducible: the same inputs give byte-identical outputs (no dates).
import { createHash } from "node:crypto";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const vendorDir = path.dirname(fileURLToPath(import.meta.url));
const repoRoot = path.resolve(vendorDir, "..", "..");
const outTs = path.join(repoRoot, "src", "xtermVendor.generated.ts");
const outNotices = path.join(vendorDir, "THIRD_PARTY_NOTICES.txt");
const outBuild = path.join(vendorDir, "dist", "build.json");
const runtimeJs = path.join(vendorDir, "dist", "xterm-runtime.js");
const modules = path.join(vendorDir, "node_modules");

const HEADER = "// Generated by scripts/build-xterm-vendor.sh — do not edit.\n";

function directDeps() {
  const pkg = JSON.parse(
    fs.readFileSync(path.join(vendorDir, "package.json"), "utf8"),
  );
  return Object.keys(pkg.dependencies).sort();
}

function writeNotices() {
  const parts = [
    "Aed Terminal — third-party software notices",
    "Generated by scripts/build-xterm-vendor.sh",
    "",
    "Vendored packages (name@version — license):",
    "",
  ];
  for (const name of directDeps()) {
    const dir = path.join(modules, name);
    const pkg = JSON.parse(fs.readFileSync(path.join(dir, "package.json"), "utf8"));
    parts.push(`${name}@${pkg.version} — ${pkg.license}`);
    parts.push("-".repeat(60));
    parts.push(fs.readFileSync(path.join(dir, "LICENSE"), "utf8").trim());
    parts.push("");
  }
  fs.writeFileSync(outNotices, parts.join("\n"));
}

// The build id hashes every input, so the test suite can prove that
// XTERM_RUNTIME_JS and dist/build.json come from one build.
const buildId = createHash("sha256")
  .update(fs.readFileSync(path.join(vendorDir, "page.mjs")))
  .update(fs.readFileSync(path.join(vendorDir, "build.mjs")))
  .update(fs.readFileSync(path.join(vendorDir, "bun.lock")))
  .digest("hex")
  .slice(0, 16);

const js =
  fs.readFileSync(runtimeJs, "utf8") +
  `\n;globalThis.AedXterm={buildId:${JSON.stringify(buildId)}};\n`;
const css = fs.readFileSync(
  path.join(modules, "@xterm", "xterm", "css", "xterm.css"),
  "utf8",
);

const out =
  HEADER +
  `export const XTERM_BUILD_ID = ${JSON.stringify(buildId)};\n\n` +
  `export const XTERM_RUNTIME_JS = ${JSON.stringify(js)};\n\n` +
  `export const XTERM_CSS = ${JSON.stringify(css)};\n`;
fs.writeFileSync(outTs, out);
fs.writeFileSync(outBuild, `${JSON.stringify({ buildId }, null, 2)}\n`);
writeNotices();
console.log(
  `wrote ${path.relative(repoRoot, outTs)} (${out.length} bytes), dist/build.json and THIRD_PARTY_NOTICES.txt (build ${buildId})`,
);
